class Processor(Iface, TProcessor):
    def __init__(self, handler):
        self._handler = handler
        self._processMap = {}
        self._processMap["addBet"] = Processor.process_addBet
        self._processMap["changeBet"] = Processor.process_changeBet
        self._processMap["deleteBet"] = Processor.process_deleteBet
        self._processMap["betExists"] = Processor.process_betExists
        self._processMap["getMyBetOptions"] = Processor.process_getMyBetOptions
        self._processMap["getAllBetOptions"] = Processor.process_getAllBetOptions
        self._processMap["getSpecificBetOption"] = Processor.process_getSpecificBetOption
        self._processMap["getAllPlacedBets"] = Processor.process_getAllPlacedBets
        self._processMap["getAllPlacedBetsToABetOption"] = Processor.process_getAllPlacedBetsToABetOption
        self._processMap["placeNewBet"] = Processor.process_placeNewBet
        self._processMap["addGame"] = Processor.process_addGame
        self._processMap["endGame"] = Processor.process_endGame
        self._processMap["isGameOpen"] = Processor.process_isGameOpen
        self._processMap["getAllOpenGames"] = Processor.process_getAllOpenGames
        self._processMap["getAllClosedGames"] = Processor.process_getAllClosedGames
        self._processMap["getSpecificGame"] = Processor.process_getSpecificGame
        self._processMap["getPossibleEarningBookholder"] = Processor.process_getPossibleEarningBookholder
        self._processMap["getNumberOfBettors"] = Processor.process_getNumberOfBettors
        self._processMap["getEarningBettor"] = Processor.process_getEarningBettor
        self._processMap["getEarningBookholder"] = Processor.process_getEarningBookholder
        self._processMap["newRecommendation"] = Processor.process_newRecommendation
        self._processMap["newDay"] = Processor.process_newDay
        self._processMap["getAllRecommendations"] = Processor.process_getAllRecommendations
        self._on_message_begin = None

    def on_message_begin(self, func):
        self._on_message_begin = func

    def process(self, iprot, oprot):
        (name, type, seqid) = iprot.readMessageBegin()
        if self._on_message_begin:
            self._on_message_begin(name, type, seqid)
        if name not in self._processMap:
            iprot.skip(TType.STRUCT)
            iprot.readMessageEnd()
            x = TApplicationException(TApplicationException.UNKNOWN_METHOD, 'Unknown function %s' % (name))
            oprot.writeMessageBegin(name, TMessageType.EXCEPTION, seqid)
            x.write(oprot)
            oprot.writeMessageEnd()
            oprot.trans.flush()
            return
        else:
            self._processMap[name](self, seqid, iprot, oprot)
        return True

